  RoutingDecision,
  RoutingStrategy,
} from '../routingStrategy.js';

export class OverrideStrategy implements RoutingStrategy {
  readonly name = 'override';

  async route(
    context: RoutingContext,
    config: Config,
    _baseLlmClient: BaseLlmClient,
